Base value = new Derived();
Derived concrete = (Derived)value;
value.Draw();
Console.WriteLine(value.Name());
Console.WriteLine(concrete.Name());
value.Mark("hello");
concrete.Mark("hello");
object text = "hello";
Printer.Show(text);
Printer.Show("hello");
class Base
{
    public virtual void Draw() => Console.WriteLine("base.draw");
    public string Name() => "base.name";
    public virtual void Mark(object value) => Console.WriteLine("base.object");
}
sealed class Derived : Base
{
    public override void Draw() => Console.WriteLine("derived.draw");
    public new string Name() => "derived.name";
    public override void Mark(object value) => Console.WriteLine("derived.object");
    public void Mark(string value) => Console.WriteLine("derived.string");
}
static class Printer
{
    public static void Show(object value) => Console.WriteLine("overload.object");
    public static void Show(string value) => Console.WriteLine("overload.string");
}

