IPricePolicy[] policies = { new RegularPrice(), new VipPrice(), new CampaignPrice() };
foreach (var policy in policies) Console.WriteLine($"{policy.GetType().Name}:{policy.Price(100)}");
int checks = 0;
foreach (var policy in policies)
{
    foreach (int points in new[] { 0, 1, 100, int.MaxValue })
    {
        int price = policy.Price(points);
        if (price < 0 || price > points) throw new Exception("Contract broken");
        checks++;
    }
    try { policy.Price(-1); throw new Exception("Negative input accepted"); }
    catch (ArgumentOutOfRangeException) { checks++; }
}
Console.WriteLine($"contract checks:{checks}");
interface IPricePolicy { int Price(int points); }
sealed class RegularPrice : IPricePolicy
{
    public int Price(int points) { ArgumentOutOfRangeException.ThrowIfNegative(points); return points; }
}
sealed class VipPrice : IPricePolicy
{
    public int Price(int points) { ArgumentOutOfRangeException.ThrowIfNegative(points); return points - points / 10; }
}
sealed class CampaignPrice : IPricePolicy
{
    public int Price(int points) { ArgumentOutOfRangeException.ThrowIfNegative(points); return points - points / 5; }
}

