Counter original = new();
ICounter boxed = original;
boxed.Increment();
Counter copy = (Counter)boxed;
copy.Increment();
Console.WriteLine($"original:{original.Value};boxed:{boxed.Value};copy:{copy.Value}");
Increment(ref original);
Console.WriteLine($"after ref:{original.Value};boxed:{boxed.Value}");
static void Increment<T>(ref T counter) where T : struct, ICounter => counter.Increment();
interface ICounter { int Value { get; } void Increment(); }
struct Counter : ICounter
{
    public int Value { get; private set; }
    public void Increment() => Value++;
}

